/* HEXA BATTLEGROUNDS setup — PART 82 OF 84. Run parts in order. Safe to re-run. */ create or replace function host_attendance(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); insert into audit_log(event_id, actor, action) values (v_ev, 'host', 'attendance_export'); return (select coalesce(jsonb_agg(jsonb_build_object( 'emp_id', m.emp_id, 'email', m.email, 'name', m.name, 'squad', t.number, 'squad_name', t.name, 'squad_code', t.squad_code, 'map', a.number, 'size', (select count(*) from players q where q.team_id = t.id and q.active), 'role', p.role, 'joined_at', m.first_joined_at, 'last_seen_at', p.last_seen_at, 'points', t.points) order by a.number, t.number, m.name), '[]'::jsonb) from online_members m left join players p on p.id = m.player_id left join teams t on t.id = p.team_id left join arenas a on a.id = t.arena_id where m.event_id = v_ev); end $$; create or replace function host_online_summary(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); return jsonb_build_object( 'players', (select count(*) from online_members where event_id = v_ev), 'max_maps', _cfg(v_ev, 'online_max_maps'), 'maps', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'number', a.number, 'phase', a.phase, 'squads', (select count(*) from teams t where t.arena_id = a.id), 'ready', (select count(*) from teams t where t.arena_id = a.id and t.ready), 'full', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) = 4), 'short', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) between 1 and 2), 'players', (select count(*) from players q join teams t on t.id = q.team_id where t.arena_id = a.id and q.active)) order by a.number), '[]'::jsonb) from arenas a where a.event_id = v_ev)); end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; alter table players add column if not exists away boolean not null default false; alter table players add column if not exists away_at timestamptz; alter table players add column if not exists orig_role text; alter table players add column if not exists role2_bot boolean not null default false; alter table arenas add column if not exists watch_at timestamptz; create table if not exists squad_chat ( id bigserial primary key, team_id uuid not null references teams(id) on delete cascade, player_id uuid references players(id) on delete set null, name text not null, kind text not null default 'msg' check (kind in ('msg', 'ping', 'system')), body text not null check (char_length(body) between 1 and 240), at timestamptz not null default now() ); drop function if exists _defaults_v8(); alter function _defaults() rename to _defaults_v8; create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v8() || jsonb_build_object( 'away_seconds', 60) $$; create or replace function _sq_note(p_team uuid, p_body text) returns void language sql as $$ insert into squad_chat(team_id, name, kind, body) values (p_team, 'Hexa Air', 'system', left(p_body, 240)); select _ping_team(p_team, 'chat'); $$; create or replace function _sq_cover(p_team uuid, p_role text, p_gone uuid) returns uuid language plpgsql as $$ declare v_holder uuid; v_name text; v_gone text; begin if p_role is null or p_role = 'captain' then return null; end if; if exists (select 1 from players where team_id = p_team and active and not away and (role = p_role or role2 = p_role)) then return null; end if; select id, display_name into v_holder, v_name from players where team_id = p_team and active and not away and id <> p_gone and role is not null and role2 is null order by (role = 'captain'), joined_at limit 1; select display_name into v_gone from players where id = p_gone; if v_holder is null then perform _sq_note(p_team, '🤖 ' || coalesce(v_gone, 'A teammate') || ' is offline — nobody is free to read the ' || p_role || ' clue'); return null; end if; update players set role2 = p_role, role2_bot = true where id = v_holder; perform _sq_note(p_team, '🤖 Bot joined for ' || coalesce(v_gone, 'a teammate') || ' — ' || v_name || ' now also sees the ' || p_role || ' clue'); return v_holder; end $$; create or replace function _squad_gone(p_player uuid) returns void language plpgsql as $$ declare p players; q players; r text; v_r2 text; begin select * into p from players where id = p_player; update players set away = true, away_at = now() where id = p_player; perform _sq_note(p.team_id, '📶 ' || p.display_name || ' disconnected'); if p.role = 'captain' then select * into q from players where team_id = p.team_id and active and not away and id <> p.id and role is not null order by (role2 is not null), joined_at limit 1; if q.id is not null then r := q.role; update players set role = null where id in (p.id, q.id); update players set role = 'captain', orig_role = coalesce(orig_role, r) where id = q.id; update players set role = r, orig_role = 'captain' where id = p.id; perform _sq_note(p.team_id, '⭐ ' || q.display_name || ' is captain while ' || p.display_name || ' is away'); p.role := r; select role2 into v_r2 from players where id = q.id; if v_r2 is not null then update players set role2 = null, role2_bot = false where id = q.id; perform _sq_cover(p.team_id, v_r2, p.id); end if; end if; end if; if p.role2 is not null then update players set role2 = null, role2_bot = false where id = p.id; perform _sq_cover(p.team_id, p.role2, p.id); end if; perform _sq_cover(p.team_id, p.role, p.id); perform _ping_team(p.team_id, 'roles'); end $$; create or replace function _squad_back(p_player uuid) returns void language plpgsql as $$ declare p players; q players; r text; begin select * into p from players where id = p_player; update players set away = false, away_at = null where id = p_player; update players set role2 = null, role2_bot = false where team_id = p.team_id and role2_bot and role2 = p.role; if p.orig_role = 'captain' then select * into q from players where team_id = p.team_id and active and role = 'captain' and id <> p.id; if q.id is not null and q.orig_role is not null then r := q.orig_role; update players set role = null where id in (p.id, q.id); update players set role = 'captain', orig_role = null where id = p.id; update players set role = r, orig_role = null where id = q.id; update players set role2 = null, role2_bot = false where team_id = p.team_id and role2_bot and role2 = r; perform _sq_note(p.team_id, '⭐ ' || p.display_name || ' is back as captain'); else update players set orig_role = null where id = p.id; end if; end if; perform _sq_note(p.team_id, '✅ ' || p.display_name || ' reconnected' || case when p.role is not null then ' — the bot left' else '' end); perform _ping_team(p.team_id, 'roles'); end $$; create or replace function _squad_watch(p_arena uuid) returns boolean language plpgsql as $$ declare t record; p record; v_any boolean := false; v_away int; begin update arenas set watch_at = now() where id = p_arena and phase in ('shuttle', 'roles', 'play', 'finale') and (watch_at is null or watch_at < now() - interval '4 seconds'); if not found then return false; end if; v_away := _cfg((select event_id from arenas where id = p_arena), 'away_seconds'); for t in select tm.id from teams tm where tm.arena_id = p_arena and tm.ready and not exists (select 1 from bots b where b.team_id = tm.id) loop for p in select id from players where team_id = t.id and active and away and last_seen_at > now() - interval '20 seconds' loop perform _squad_back(p.id); v_any := true; end loop; for p in select id from players where team_id = t.id and active and not away and last_seen_at < now() - make_interval(secs => v_away) loop perform _squad_gone(p.id); v_any := true; end loop; end loop; return v_any; end $$; drop function if exists _tick_v9(uuid, boolean); alter function _tick(uuid, boolean) rename to _tick_v9; create function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare v boolean; begin if not p_force and exists (select 1 from arenas where id = p_arena and last_tick_at > now() - interval '800 milliseconds') then return false; end if; if not pg_try_advisory_xact_lock(hashtext('tick-gate' || p_arena::text)) then return false; end if; v := _tick_v9(p_arena, p_force); if _squad_watch(p_arena) then v := true; end if; return v; end $$; drop function if exists _player_state_v9(text); alter function player_state(text) rename to _player_state_v9; create function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; p players; ph text; begin v := _player_state_v9(p_token); p := _auth_player(p_token); ph := v -> 'arena' ->> 'phase'; v := v || jsonb_build_object('squad', (select coalesce(jsonb_agg(jsonb_build_object( 'name', q.display_name, 'me', q.id = p.id, 'role', q.role, 'role2', q.role2, 'bot2', q.role2_bot, 'status', case when q.away then 'away' when q.last_seen_at > now() - interval '15 seconds' then 'on' else 'weak' end) order by q.joined_at), '[]'::jsonb) from players q where q.team_id = p.team_id and q.active)); v := jsonb_set(v, '{me}', (v -> 'me') || jsonb_build_object('role2', p.role2, 'role2_bot', p.role2_bot)); v := v || jsonb_build_object('chat_last', (select max(id) from squad_chat where team_id = p.team_id)); if ph not in ('results', 'ended') then v := v - 'leaderboard'; end if; return v; end $$; drop function if exists _spectator_state_v9(text); alter function spectator_state(text) rename to _spectator_state_v9; create function spectator_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; begin v := _spectator_state_v9(p_token); if v -> 'arena' is not null and (v -> 'arena' ->> 'phase') not in ('results', 'ended') then v := v - 'leaderboard'; if jsonb_typeof(v -> 'squads') = 'array' then v := jsonb_set(v, '{squads}', (select coalesce(jsonb_agg(s - 'points' - 'final_points' - 'rank'), '[]'::jsonb) from jsonb_array_elements(v -> 'squads') s)); end if; end if; return v; end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; do $$ declare t text; begin foreach t in array array['squad_chat'] loop execute format('alter table %I enable row level security', t); execute format('revoke all on table %I from anon, authenticated', t); end loop; end $$; drop function if exists _defaults_v9(); alter function _defaults() rename to _defaults_v9; create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v9() || jsonb_build_object( 'online_started', 0) $$; create or replace function _online_arena(p_ev uuid) returns uuid language plpgsql as $$ declare v_arena uuid; begin if _cfg(p_ev, 'online_started') = 1 then raise exception 'GAME_STARTED'; end if; select id into v_arena from arenas where event_id = p_ev order by number limit 1; if v_arena is null then insert into arenas(event_id, number, name) values (p_ev, 1, 'Map 1') returning id into v_arena; end if; return v_arena; end $$; create or replace function _online_open(p_team uuid) returns boolean language sql stable as $$ select exists (select 1 from teams t join arenas a on a.id = t.arena_id where t.id = p_team and (a.phase in ('lobby', 'boarding', 'shuttle', 'roles') or (a.phase = 'play' and not t.dropped and t.jump_at is null))) $$; create or replace function _online_late_team(p_ev uuid) returns uuid language sql stable as $$ select t.id from teams t join arenas a on a.id = t.arena_id where t.event_id = p_ev and t.ready and _online_open(t.id) and (select count(*) from players q where q.team_id = t.id and q.active) < 4 order by (select count(*) from players q where q.team_id = t.id and q.active) desc, a.number, t.number limit 1 $$; create or replace function _online_seal_event(p_ev uuid) returns jsonb language plpgsql as $$ declare u record; v record; x record; v_t uuid; v_need int; v_moved int := 0; v_left int := 0; begin for u in select t.id from teams t where t.event_id = p_ev order by _online_size(t.id) desc, t.open_squad, t.created_at loop continue when _online_size(u.id) not between 1 and 2; loop exit when _online_size(u.id) >= 3; select t.id into v_t from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) between 1 and 2 and _online_size(t.id) <= 4 - _online_size(u.id) order by _online_size(t.id) desc, t.created_at limit 1; exit when v_t is null; for x in select id from players where team_id = v_t and active loop perform _online_move(x.id, u.id); v_moved := v_moved + 1; end loop; end loop; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) between 1 and 2 loop for x in select id from players where team_id = u.id and active loop select t.id into v_t from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) = 3 order by t.open_squad desc, t.created_at limit 1; exit when v_t is null; perform _online_move(x.id, v_t); v_moved := v_moved + 1; end loop; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) between 1 and 2 loop v_need := 3 - _online_size(u.id); for v in select t.id from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) = 4 order by t.open_squad desc, t.created_at limit v_need loop select id into v_t from players where team_id = v.id and active order by joined_at desc limit 1; perform _online_move(v_t, u.id); v_moved := v_moved + 1; end loop; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) = 1 loop select t.id into v_t from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) = 3 order by t.open_squad desc, t.created_at limit 1; if v_t is not null then select id into v_t from players where team_id = v_t and active order by joined_at desc limit 1; perform _online_move(v_t, u.id); v_moved := v_moved + 1; end if; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) = 1 loop v_left := v_left + 1; end loop; update teams t set ready = (select count(*) from players q where q.team_id = t.id and q.active) >= 2, roster_locked = (select count(*) from players q where q.team_id = t.id and q.active) >= 4 where t.event_id = p_ev; return jsonb_build_object('moved', v_moved, 'left_out', v_left); end $$; create or replace function _online_seal(p_arena uuid) returns jsonb language plpgsql as $$ declare v jsonb; begin v := jsonb_build_object('moved', 0, 'left_out', 0); update teams t set ready = true where t.arena_id = p_arena and (select count(*) from players q where q.team_id = t.id and q.active) >= 2; return v; end $$;
